const { job, context } = $input.first().json;
const b = context.business ?? {};
const inspection = (b.inspections ?? [])[0] ?? {};
const system = "You analyse Australian trade-business websites and return strict JSON only.";
const user = [
  `Business: ${b.name}`,
  `Website: ${b.website ?? 'unknown'}`,
  `Categories: ${(b.categories ?? []).join(', ')}`,
  `Location: ${[b.suburb, b.city, b.state].filter(Boolean).join(', ')}`,
  `Site title: ${inspection.siteTitle ?? ''}`,
  `Site description: ${inspection.siteSummary ?? ''}`,
  `Existing profile notes: ${JSON.stringify(b.profile ?? {})}`,
  '',
  'Return JSON: {"summary": string, "services": string[], "serviceAreas": string[], "differentiators": string[]}.',
  'Only state what the evidence supports — never invent qualifications, prices, or guarantees.'
].join('\n');
return [{ json: { jobId: job.id, system, user } }];

