const { job, context } = $input.first().json;
const b = context.business ?? {};
const a = context.article ?? {};
const p = b.profile ?? {};
const brief = a.researchBrief ?? {};
const system = "You write genuinely useful SEO articles in Australian English for trade businesses. Return strict JSON only.";
const user = [
  `Client business: ${b.name} (${[b.city, b.state].filter(Boolean).join(', ')})`,
  `Website: ${b.website ?? ''}`,
  `Services: ${(p.services ?? []).join(', ')}`,
  `Service areas: ${(p.serviceAreas ?? []).join(', ')}`,
  `Article topic: ${a.title}`,
  `Research brief: ${JSON.stringify(brief)}`,
  `Writer notes: ${p.notesForWriter ?? ''}`,
  '',
  'Write a ~1200-1600 word article. Structure: H1 title (returned separately), intro, H2/H3 sections, a natural call to action mentioning the business.',
  'Australian English, local context, practical and accurate. Match the search intent in the brief.',
  'Weave suggested internal links in naturally where they fit.',
  'Do NOT invent prices, qualifications, project experience, testimonials, or guarantees.',
  'Return JSON: {"title": string, "contentHtml": "<h2>…</h2><p>…</p>… (HTML without the H1 — title goes in the title field)", "meta": {"metaDescription": string, "keywords": string[]}}.'
].join('\n');
return [{ json: { jobId: job.id, system, user } }];

const item = $input.first().json;
if (item.error || !item.choices?.[0]?.message?.content) {
  return [{ json: { jobId: item.jobId ?? null, ok: false, error: item.error?.message ?? item.message ?? 'OpenAI call failed' } }];
}
let result;
try {
  result = JSON.parse(item.choices[0].message.content);
} catch (e) {
  return [{ json: { jobId: item.jobId, ok: false, error: 'Model returned non-JSON output' } }];
}
const usage = item.usage ?? {};
const costCents = Math.ceil(((usage.prompt_tokens ?? 0) * 0.00015 + (usage.completion_tokens ?? 0) * 0.0006) * 100);
return [{ json: { jobId: item.jobId, ok: true, result, costCents } }];
